import math

def is_prime(n):
    """Checks if a positive integer n is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def calculate_P(x, y, z):
    """Calculates P = y^x * z^y * x^z, handling potential complex/non-integer results for negative bases/exponents."""
    try:
        # Python's built-in pow handles integer exponents correctly, even for negative bases.
        # However, we must be careful if the result is zero or negative before checking for primality.

        # Term 1: y^x
        if y == 0:
            if x == 0:
                term1 = 1 # Convention 0^0 = 1 in many contexts, though context matters. Here we assume it's safe.
            elif x < 0:
                return None # Division by zero if exponent is negative
            else:
                term1 = 0
        else:
            term1 = pow(y, x)

        # Term 2: z^y
        if z == 0:
            if y == 0:
                term2 = 1
            elif y < 0:
                return None
            else:
                term2 = 0
        else:
            term2 = pow(z, y)

        # Term 3: x^z
        if x == 0:
            if z == 0:
                term3 = 1
            elif z < 0:
                return None
            else:
                term3 = 0
        else:
            term3 = pow(x, z)

        P = term1 * term2 * term3
